sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var sys_id = api.state.sys_id;
    const rows = api.state.records;
    var test = [];
    var arr = [];
    test.oya = sys_id;

    const keys = Object.keys(rows);

    keys.forEach(function(key) {
        console.log(rows[key]);
        var sysId = rows[key].cells.user_id.metadata.referenceSysId;
        if (arr.indexOf(sysId) === -1) {
            arr.push(sysId);
        }
    });
    test.records = arr.join(',');

    api.data.insert_test_1.execute(test);

}
